def _value_to_range_string(value: float) -> str:
    """
    Convert a numeric value to a range string format used in _REPORT_DATA.
    
    Args:
        value: Numeric value
        
    Returns:
        str: Range string like "0-0.99", "1-1.99", "2-2.99", "3-3.99"
    """
    if 0 <= value < 1:
        return "0-0.99"
    elif 1 <= value < 2:
        return "1-1.99"
    elif 2 <= value < 3:
        return "2-2.99"
    elif 3 <= value < 4:
        return "3-3.99"
    else:
        return "3-3.99"  # Default for values >= 4


def get_report_text(label, value):
    """
    Retrieves the text based on the Label (عامل) and Value.

    Args:
        label (str): The label text (first column of Excel).
        value (str/int/float): The value header (other columns of Excel) or numeric value.

    Returns:
        str: The text found in the cell, or a default message if not found.
    """
    label_key = str(label).strip()

    # Convert numeric value to range string if needed
    if isinstance(value, (int, float)):
        value_key = _value_to_range_string(float(value))
    else:
        value_key = str(value).strip()

    if label_key in _REPORT_DATA:
        label_data = _REPORT_DATA[label_key]

        if value_key in label_data:
            return label_data[value_key]
        else:
            return f"Error: Value '{value}' not found for Label '{label}'."
    else:
        return f"Error: Label '{label}' not found."


def get_statefast_value(value: float) -> str:
    """
    Get state text based on value ranges.
    
    Args:
        value: The calculated value from scl_calc_data
        
    Returns:
        str: State text based on value range:
            - 0-0.99: "نرمال"
            - 1-1.99: "نیازمند توجه"
            - 2-2.99: "نگران کننده"
            - 3-3.99: "بحرانی"
            - >= 4: "بحرانی" (default to highest)
    """
    if 0 <= value < 1:
        return "نرمال"
    elif 1 <= value < 2:
        return "نیازمند توجه"
    elif 2 <= value < 3:
        return "نگران کننده"
    elif 3 <= value < 4:
        return "بحرانی"
    else:
        return "بحرانی"  # Default for values >= 4


def get_interfast_value(value: float) -> str:
    """
    Get intervention priority text based on value ranges.
    
    Args:
        value: The calculated value from scl_calc_data
        
    Returns:
        str: Intervention priority text based on value range:
            - 0-0.99: "عدم نیاز"
            - 1-1.99: "متوسط"
            - 2-2.99: "زیاد"
            - 3-3.99: "فوری"
            - >= 4: "فوری" (default to highest)
    """
    if 0 <= value < 1:
        return "عدم نیاز"
    elif 1 <= value < 2:
        return "متوسط"
    elif 2 <= value < 3:
        return "زیاد"
    elif 3 <= value < 4:
        return "فوری"
    else:
        return "فوری"  # Default for values >= 4
